#!/usr/bin/env python3
"""Card c2 (squad round 6): orbit graph of the stabiliser St of the 756 set inside N(<h>) (from normaliser.py),
projectively (g and -g identified), warm-started with the 756 set.  usage: stab_graph.py TEXACT THEUR SEED TAG [--sub K]
--sub K: use only the subgroup generated by the first K projective elements listed (default: whole stabiliser)."""
import argparse
import os
import subprocess
import sys
import time

import numpy as np

from common import HERE, L, MMUL, MPOW, h_matrix, read_points, write_gens

WCLQ = os.path.join(HERE, 'wclq2')
WORK = os.path.join(HERE, 'work')
GENS = os.path.join(HERE, 'gens')
p = 11


def proj_key(g):
    """canonical key of the projective class of g (up to sign)."""
    a = g % p
    b = (-g) % p
    ka, kb = a.tobytes(), b.tobytes()
    return min(ka, kb)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('texact', type=float)
    ap.add_argument('theur', type=float)
    ap.add_argument('seed', type=int)
    ap.add_argument('tag')
    ap.add_argument('--gens', type=int, default=0, help='if >0: use a random subset of this many elements of the group')
    args = ap.parse_args()
    t0 = time.time()
    d = np.load(os.path.join(HERE, 'norm_stab.npz'))
    mats = d['mats']
    seen = {}
    for g in mats:
        seen.setdefault(proj_key(g), g)
    projs = list(seen.values())
    print(f'stabiliser: {len(mats)} matrices, {len(projs)} projective elements', flush=True)
    perms = [L.perm_of(g) for g in projs]
    lab = L.orbit_labels(perms)
    sizes, rep, good = L.analyse(lab)
    K = int(good.size)
    print(f'group orbits {sizes.size} (sizes {sorted(set(sizes.tolist()))}), good K={K} ({time.time() - t0:.1f}s)', flush=True)
    S = read_points(os.path.join(HERE, '..', '..', 'd13D7_r4', 'c1', 'best_idx.txt'))
    labs = np.unique(lab[S])
    union = np.flatnonzero(np.isin(lab, labs))
    print(f'756 set is a union of {labs.size} orbits of the stabiliser: {np.array_equal(np.sort(union), np.sort(S))}',
          flush=True)
    pos = np.full(sizes.size, -1, np.int64)
    pos[good] = np.arange(K)
    gi = pos[labs]
    assert np.all(gi >= 0)
    init_path = os.path.join(WORK, f'{args.tag}_init.txt')
    os.makedirs(WORK, exist_ok=True)
    with open(init_path, 'w') as f:
        f.write('\n'.join(map(str, gi.tolist())) + '\n')
    init_w = int(sizes[labs].sum())
    rows = L.compat_packed(lab, rep, good)
    w = sizes[good]
    gbin = os.path.join(WORK, f'{args.tag}.bin')
    L.write_graph_packed(gbin, rows, w)
    print(f'graph written, density {L.packed_density(rows):.4f}, warm weight {init_w} ({time.time() - t0:.1f}s)',
          flush=True)
    out = os.path.join(WORK, f'{args.tag}_s{args.seed}.clq')
    cmd = [WCLQ, gbin, str(args.texact), str(args.theur), str(args.seed), out, init_path]
    t1 = time.time()
    res = subprocess.run(cmd, capture_output=True, text=True)
    weight, opt, verts = L.read_clique(out)
    chosen = good[np.array(verts, dtype=np.int64)]
    idx = np.flatnonzero(np.isin(lab, chosen))
    ok = idx.size == weight and L.pairwise_ok(idx)
    err = [l for l in res.stderr.splitlines() if l.strip()]
    print(f'RESULT weight {weight} optimal {opt} verified {ok} wall {time.time() - t1:.1f}s | {"; ".join(err[-4:])}',
          flush=True)
    if ok:
        dst = os.path.join(WORK, f'{args.tag}_best.idx')
        with open(dst, 'w') as f:
            f.write(f'# {weight} points, {args.tag} (verified pairwise opposite)\n'
                    + '\n'.join(map(str, np.sort(idx).tolist())) + '\n')
        print(f'saved {dst}', flush=True)
    os.remove(out)
    os.remove(gbin)
    print(f'total wall {time.time() - t0:.1f}s', flush=True)


if __name__ == '__main__':
    main()
